on conflict(word,pos,definition) do update set lemma=excluded.lemma,example=coalesce(excluded.example,public.lexicon.example),difficulty=excluded.difficulty,register=coalesce(excluded.register,public.lexicon.register),source=excluded.source,source_url=excluded.source_url,native_score=excluded.native_score,learning_value=excluded.learning_value,contextual_diversity=excluded.contextual_diversity,prevalence=excluded.prevalence,content_status='ready';
